import { create } from 'zustand';
import { immer } from 'zustand/middleware/immer';
import type { RecoverySnapshot, RecoveryLog, FormData } from '../types';

interface SnapshotState {
  snapshots: RecoverySnapshot[];
  recoveryLogs: RecoveryLog[];
  form: FormData;
  isSubmitting: boolean;

  addSnapshot: (state: any) => void;
  getLatestSnapshot: () => RecoverySnapshot | null;
  addLog: (log: Omit<RecoveryLog, 'id' | 'timestamp'>) => void;
  clearLogs: () => void;

  // Form state management (lifted from DemoForm into the recovery layer)
  updateForm: (form: Partial<FormData>) => void;
  setSubmitting: (isSubmitting: boolean) => void;
  takeSnapshot: (form: FormData) => void;
  restoreFromSnapshot: () => void;
}

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

export const useSnapshotStore = create<SnapshotState>()(
  immer((set, get) => ({
    snapshots: [],
    recoveryLogs: [],
    form: { name: '', email: '', address: '', phone: '', message: '' },
    isSubmitting: false,

    addSnapshot: (state) =>
      set((draft) => {
        const snapshot: RecoverySnapshot = {
          state: JSON.parse(JSON.stringify(state)),
          timestamp: Date.now(),
          id: generateId(),
        };
        draft.snapshots.push(snapshot);
        // Keep only last 50 snapshots to manage memory
        if (draft.snapshots.length > 50) {
          draft.snapshots.shift();
        }
      }),

    getLatestSnapshot: () => {
      const snapshots = get().snapshots;
      return snapshots.length > 0 ? snapshots[snapshots.length - 1] : null;
    },

    addLog: (log) =>
      set((draft) => {
        draft.recoveryLogs.push({
          ...log,
          id: generateId(),
          timestamp: Date.now(),
        });
      }),

    clearLogs: () =>
      set((draft) => {
        draft.recoveryLogs = [];
      }),

    // Capture a checkpoint of the current form
    takeSnapshot: (form) => {
      const state = { form };
      get().addSnapshot(state);
      get().addLog({
        type: 'snapshot',
        message: `STATE SNAPSHOT - Size: ${JSON.stringify(state).length} bytes`,
        stateSize: JSON.stringify(state).length,
      });
    },

    // Sync form state into the recovery layer (called from DemoForm)
    updateForm: (form) =>
      set((draft) => {
        draft.form = { ...draft.form, ...form };
      }),

    setSubmitting: (isSubmitting) => set((draft) => {
      draft.isSubmitting = isSubmitting;
    }),

    // Restore the form from the latest snapshot
    restoreFromSnapshot: () => {
      const snapshot = get().getLatestSnapshot();
      if (!snapshot) {
        get().addLog({
          type: 'error',
          message: 'No snapshot available for recovery',
        });
        return;
      }
      get().addLog({
        type: 'recovery',
        message: 'RECOVERY EXECUTED - Restoring from checkpoint...',
      });
      set((draft) => {
        // Snapshots may be stored as { form } (via takeSnapshot before an
        // error) or as the raw form object (DemoForm's periodic checkpoint).
        // Handle both so recovery always restores the form fields.
        const state = snapshot.state as any;
        const restored = state?.form ?? state;
        draft.form = { ...restored };
        draft.isSubmitting = false;
      });
      get().addLog({
        type: 'success',
        message: '✅ RECOVERED - State consistent, form data preserved',
      });
    },
  }))
);

// Helper functions
export const takeSnapshot = (state: any) => {
  useSnapshotStore.getState().addSnapshot(state);
  useSnapshotStore.getState().addLog({
    type: 'snapshot',
    message: `STATE SNAPSHOT - Size: ${JSON.stringify(state).length} bytes`,
    stateSize: JSON.stringify(state).length,
  });
};

export const getLatestSnapshot = (): RecoverySnapshot | null => {
  return useSnapshotStore.getState().getLatestSnapshot();
};

export const addRecoveryLog = (log: Omit<RecoveryLog, 'id' | 'timestamp'>) => {
  useSnapshotStore.getState().addLog(log);
};

export const clearRecoveryLogs = () => {
  useSnapshotStore.getState().clearLogs();
};

export const getRecoveryLogs = (): RecoveryLog[] => {
  return useSnapshotStore.getState().recoveryLogs;
};

export const updateForm = (form: Partial<FormData>) =>
  useSnapshotStore.getState().updateForm(form);
export const setSubmitting = (isSubmitting: boolean) =>
  useSnapshotStore.getState().setSubmitting(isSubmitting);
export const restoreFromSnapshot = () => useSnapshotStore.getState().restoreFromSnapshot();
export const getForm = () => useSnapshotStore.getState().form;
